function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function safe(val) {
  return val === null || val === undefined ? '' : String(val);
}

const data = $json;
const criminals = toArray(data?.criminals?.criminal);

if (criminals.length === 0) {
  return [{ json: {
    record_id: '', full_name: 'NORESULTS',
    first_name: '', middle_name: '', last_name: '',
    dob: '', current_age: '', is_sex_offender: '',
    city: '', county: '', state: '', zip: '',
    crime_record_no: '', source_state: '', case_number: '',
    arresting_agency: '', crime_county: '', court: '',
    status: '', conviction: '', conviction_date: '',
    disposition: '', disposition_date: '', crime_type: '',
    classification: '', offense_code: '', offense_description_1: '',
    offense_description_2: '', case_type: '', sentence: '',
    charges_filed_date: '', violation_date: '',
    warrant: '', probation: '', comments: ''
  }}];
}

const results = [];

for (let ci = 0; ci < criminals.length; ci++) {
  const criminal = criminals[ci];
  const suspect = criminal?.suspect || {};
  const name = suspect?.name || {};
  const address = suspect?.address || {};

  const firstName  = safe(name.firstName);
  const middleName = safe(name.middleName);
  const lastName   = safe(name.lastName);
  const fullName   = [firstName, middleName, lastName].filter(Boolean).join(' ');

  const crimeDetailsList = toArray(criminal?.crimeDetailsRecords?.crimeDetails);

  if (crimeDetailsList.length === 0) {
    results.push({ json: {
      record_id: String(ci + 1),
      full_name: fullName, first_name: firstName,
      middle_name: middleName, last_name: lastName,
      dob: safe(suspect.DOB), current_age: safe(suspect.currentAge),
      is_sex_offender: safe(suspect.isSexOffender),
      city: safe(address.city), county: safe(address.county),
      state: safe(address.state), zip: safe(address.zip),
      crime_record_no: '', source_state: '', case_number: '',
      arresting_agency: '', crime_county: '', court: '',
      status: '', conviction: '', conviction_date: '',
      disposition: '', disposition_date: '', crime_type: '',
      classification: '', offense_code: '', offense_description_1: '',
      offense_description_2: '', case_type: '', sentence: '',
      charges_filed_date: '', violation_date: '',
      warrant: '', probation: '', comments: ''
    }});
    continue;
  }

  for (let di = 0; di < crimeDetailsList.length; di++) {
    const cd = crimeDetailsList[di];
    results.push({ json: {
      record_id: (ci + 1) + '-' + (di + 1),
      full_name: fullName, first_name: firstName,
      middle_name: middleName, last_name: lastName,
      dob: safe(suspect.DOB), current_age: safe(suspect.currentAge),
      is_sex_offender: safe(suspect.isSexOffender),
      city: safe(address.city), county: safe(address.county),
      state: safe(address.state), zip: safe(address.zip),
      crime_record_no: (ci + 1) + '-' + (di + 1),
      source_state: safe(cd.sourceState),
      case_number: safe(cd.caseNumber),
      arresting_agency: safe(cd.arrestingAgency),
      crime_county: safe(cd.crimeCounty),
      court: safe(cd.court),
      status: safe(cd.status),
      conviction: safe(cd.conviction),
      conviction_date: safe(cd.convictionDate),
      disposition: safe(cd.disposition),
      disposition_date: safe(cd.dispositionDate),
      crime_type: safe(cd.crimeType),
      classification: safe(cd.classification),
      offense_code: safe(cd.offenseCode),
      offense_description_1: safe(cd.offenseDescription1),
      offense_description_2: safe(cd.offenseDescription2),
      case_type: safe(cd.caseType),
      sentence: safe(cd.sentence),
      charges_filed_date: safe(cd.chargesFiledDate),
      violation_date: safe(cd.violationDate),
      warrant: safe(cd.warrant),
      probation: safe(cd.probation),
      comments: safe(cd.comments)
    }});
  }
}

return results;

const items = $input.all();
const groups = {};
for (const it of items) {
  const j = it.json;
  const fn = (j.full_name || '').toString();
  if (!fn || fn === 'NORESULTS' || fn === 'INVALID_INPUT') continue;
  const key = ((j.first_name||'') + '|' + (j.last_name||'') + '|' + (j.state||'')).toUpperCase();
  if (!groups[key]) {
    groups[key] = { full_name: fn, first_name: j.first_name||'', last_name: j.last_name||'', state: j.state||'', offense_count: 0, felony_count: 0, misdemeanor_count: 0, is_sex_offender: 'No', latest_conviction: '', _ts: -Infinity };
  }
  const g = groups[key];
  const hasOffense = String(j.crime_record_no||'') !== '' || String(j.case_number||'') !== '';
  if (hasOffense) {
    g.offense_count++;
    const sev = String(j.severity||'').toUpperCase();
    if (sev === 'FELONY') g.felony_count++;
    else if (sev === 'MISDEMEANOR') g.misdemeanor_count++;
  }
  if (String(j.is_sex_offender||'').toLowerCase() === 'yes') g.is_sex_offender = 'Yes';
  const cd = String(j.conviction_date||'');
  const t = Date.parse(cd);
  if (!isNaN(t) && t > g._ts) { g._ts = t; g.latest_conviction = cd; }
}
const out = [];
for (const k of Object.keys(groups)) {
  const g = groups[k];
  const risk = (g.is_sex_offender === 'Yes' || g.felony_count > 0) ? 'HIGH' : (g.offense_count > 0 ? 'MEDIUM' : 'LOW');
  out.push({ json: {
    full_name: g.full_name, first_name: g.first_name, last_name: g.last_name, state: g.state,
    offense_count: g.offense_count, felony_count: g.felony_count, misdemeanor_count: g.misdemeanor_count,
    is_sex_offender: g.is_sex_offender, latest_conviction: g.latest_conviction, risk_level: risk,
    summary_date: new Date().toISOString()
  }});
}
return out;
